To create a C++ function that converts Markdown formatted text to HTML formatted text, you can use a third-party library like `markdown-cpp`. Here's a simple function that demonstrates how to achieve this:

```cpp
#include <iostream>
#include <string>
#include <markdown-cpp/markdown.h>

std::string markdownToHtml(const std::string& markdownText) {
    markdown::Markdown md;
    std::string htmlText;
    md.convert(markdownText, htmlText);
    return htmlText;
}

int main() {
    std::string markdownText = "# Hello, World!\nThis is a paragraph.";
    std::string htmlText = markdownToHtml(markdownText);
    std::cout << "Markdown Text: " << markdownText << std::endl;
    std::cout << "HTML Text: " << htmlText << std::endl;
    return 0;
}
```

